document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll("[data-toggle-section]").forEach(function(t){t.addEventListener("click",function(){var t=this.getAttribute("data-toggle-section");document.querySelectorAll("[data-toggle-section]").forEach(function(t){t.classList.remove("bg_active")}),this.classList.add("bg_active"),document.querySelectorAll("[data-section]").forEach(function(t){t.style.transition="opacity 0.3s",t.style.opacity="0",setTimeout(function(){t.classList.add("hidden")},300)});var e=document.querySelector('[data-section="'+t+'"]');e&&setTimeout(function(){e.classList.remove("hidden"),e.style.transition="opacity 0.3s",e.style.opacity="0",setTimeout(function(){e.style.opacity="1"},10)},300)})})});